        .byline {
            font-family: "Times New Roman", serif;
            font-size: 14pt;
            text-align: center;
            margin-bottom: 40px;
            font-style: italic;
        }

        /* Sections */
        h2 {
            font-family: "Times New Roman", serif;
            font-size: 18pt;
            text-align: center;
            margin-top: 50px;
            margin-bottom: 20px;
            text-decoration: underline;
        }

        /* Paragraphs */
        p {
            font-size: 12pt;
            text-align: justify;
            margin-bottom: 18px;
            text-indent: 30px;
        }

        /* Quote blocks */
        .quote {
            font-family: "Times New Roman", serif;
            font-size: 14pt;
            font-style: italic;
            text-align: center;
            margin: 30px 0;
            border-left: 3px solid #000;
            padding-left: 20px;
        }

        /* Lists */
        ul, ol {
            margin-bottom: 20px;
            padding-left: 40px;
        }

        li {
            font-size: 12pt;
            margin-bottom: 8px;
        }

